file.specification:

// Props:
//   isOpen: boolean
//   onClose: () => void
//   initialTab?: 'THEME' | 'AUDIO' | 'SANDBOX' | 'ACCOUNT' | 'ADS'

// Modal: centered overlay, max-width 480px, max-height 80dvh.
// Backdrop: rgba(0,0,0,0.7) with blur(4px).
// Close button: X in top-right corner (text "X", not an icon component).
// ACCOUNT tab positioned immediately LEFT of the X close button in the tab row.
// Gear trigger: U+2699 Unicode character (not emoji, not lucide icon).

// TAB: THEME
//   Dark/Light toggle (was ThemeToggle.tsx — absorb it here)
//   Primary accent color picker: 6 swatches (amber/violet/emerald/sky/rose/slate)
//   Font size: Small / Medium / Large (affects game number rendering only)

// TAB: AUDIO
//   Master volume slider 0-100
//   Individual toggles: Chain sounds | Match sounds | Farkle sound | Bank sound | Bomb sounds
//   All Web Audio API — no asset files

// TAB: SANDBOX
//   Placeholder: "Sandbox available in SOLO modes only"
//   When in SOLO mode: renders SandboxTab component (already designed)
//   Import SandboxTab lazily (React.lazy) — it is heavy

// TAB: ACCOUNT
//   Shows current UserProfile (username, color, ascii art preview)
//   FD balance display (from useWallet)
//   PDX balance display (from useWallet) — grayed out with "Coming Soon" if not live
//   "Edit Profile" button → triggers profile edit flow (inline, not new screen)
//   Skill score display: "Your Skill Rating: {score}/100" (from last 10 sessions avg)

// TAB: ADS
//   Toggle: "Rewarded Ads" on/off (persisted in localStorage)
//   When on: show "Watch an ad to earn +50 FD" button
//   Rewarded ad slot: placeholder callback prop onRewardedAdRequest: () => void
//   Interstitial frequency setting: "After every 3/5/10 rounds" selector
//   Current session FD earned from ads: display counter
//   Privacy note: "Ads are provided by [network]. View privacy policy."
//   Note: ADS tab is visible only when adsEnabled flag is true in app config.
